// Simple rate limiting
const rateLimit = {};

const applyRateLimit = (req, res, next) => {
  const ip = req.ip;
  const now = Date.now();
  const windowMs = 15 * 60 * 1000; // 15 minutes

  if (!rateLimit[ip]) {
    rateLimit[ip] = { count: 1, firstRequest: now };
  } else {
    // Clear expired requests
    if (now - rateLimit[ip].firstRequest > windowMs) {
